const results = [];

// ==========================================
// CONFIGURACIÓN MANUAL PARA DATA ANTIGUA
// ==========================================
const anioTarget = 2026; // Cambia esto al año que quieras
const mesTarget = 8;     // Cambia esto al mes que quieras (1 = Enero, 2 = Febrero, 3 = Marzo...)

const shortYear = String(anioTarget).slice(-2);
const monthNum = String(mesTarget).padStart(2, '0');
const meses = ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "set", "oct", "nov", "dic"];
const monthName = meses[mesTarget - 1];

// Truco de JS para saber exactamente cuántos días tuvo ese mes (incluso si fue bisiesto)
const diasDelMes = new Date(anioTarget, mesTarget, 0).getDate();

// Bucle desde el día 1 hasta el ÚLTIMO día de ese mes histórico
for (let day = 1; day <= diasDelMes; day++) {
  // En JS, los meses empiezan en 0, por eso restamos 1 al mesTarget
  const d = new Date(anioTarget, mesTarget - 1, day);

  // Nos saltamos domingos (0) y sábados (6)
  if (d.getDay() === 0 || d.getDay() === 6) continue;

  const paddedDay = String(day).padStart(2, '0');
  const url = `https://siea.midagri.gob.pe/files/datos_estadisticas/diarias/mml/${anioTarget}/${monthNum}/sisap-ingreso-gmml-${paddedDay}${monthName}${shortYear}.pdf`;

  results.push({
    json: {
      fecha_archivo: `${paddedDay}/${monthNum}/${anioTarget}`,
      url_pdf: url
    }
  });
}

return results;

const items = $input.all();
const results = [];

const unidadesValidas = [
  "Kilogramo",
  "Atado",
  "Atado Grande",
  "Cajon",
  "Cajón",
  "Cajon Chico",
  "Cajón Chico",
  "Saco",
  "Saco Chico",
  "Bolsa",
  "Mano",
  "Docena",
  "Ciento",
  "Paquete",
  "Unidad"
];

function esLineaVolumen(linea) {
  const tokens = linea.split(/\s+/);

  return tokens.every(token =>
    token === ":" ||
    /^-?\d+(?:\.\d+)?$/.test(token)
  );
}

function esCabeceraOEstado(linea) {
  const ignorar = [
    "Estable",
    "En Baja",
    "En Alza",
    "Baja Notable",
    "Alza Notable",
    "PRODUCTOS",
    "Productos",
    "Promedio",
    "Precio promedio",
    "Ayer Hoy"
  ];

  return ignorar.includes(linea) ||
         linea.includes("Masa de Ingreso") ||
         linea.includes("Masa de ingreso") ||
         linea.includes("Precio (S/") ||
         linea.includes("Precios S/");
}

for (const item of items) {

  if (!item.json.text) continue;

  const lines = item.json.text
    .split("\n")
    .map(line => line.trim())
    .filter(line => line !== "");

  // ==============================
  // FECHA DEL PDF
  // ==============================
  let fechaHistorica = new Date().toISOString().split("T")[0];

  if (item.json.info?.CreationDate) {
    const rawDate = item.json.info.CreationDate;

    const year = rawDate.substring(2, 6);
    const month = rawDate.substring(6, 8);
    const day = rawDate.substring(8, 10);

    fechaHistorica = `${year}-${month}-${day}`;
  }

  // ==============================
  // BUSCAMOS LAS UNIDADES
  // ==============================
  for (let i = 0; i < lines.length; i++) {

    const unidad = lines[i];

    if (!unidadesValidas.includes(unidad)) {
      continue;
    }

    // ==============================
    // 1. BUSCAR PRODUCTO HACIA ATRÁS
    // ==============================
    let productoIndex = i - 1;

    while (
      productoIndex >= 0 &&
      (esLineaVolumen(lines[productoIndex]) ||
       esCabeceraOEstado(lines[productoIndex]))
    ) {
      productoIndex--;
    }

    if (productoIndex < 0) continue;

    const producto = lines[productoIndex];

    // Evitar encabezados falsos
    if (
      producto.includes("Unidad") ||
      producto.includes("Últimos") ||
      producto.includes("lunes") ||
      producto.includes("martes") ||
      producto.includes("miércoles") ||
      producto.includes("jueves") ||
      producto.includes("viernes")
    ) {
      continue;
    }

    // ==============================
    // 2. RECONSTRUIR VOLUMEN
    // ==============================
    const volumenPartes = [];

    for (let j = productoIndex + 1; j < i; j++) {
      if (esLineaVolumen(lines[j])) {
        volumenPartes.push(lines[j]);
      }
    }

    const volumenRaw = volumenPartes.join(" ");

    const volumenes = volumenRaw
      .split(/\s+/)
      .filter(v => v !== "");

    // Orden MIDAGRI:
    // [0] ayer
    // [1] hoy
    // [2] promedio 7 días
    // [3] promedio 4 semanas

    let volumenHoy = null;

    if (
      volumenes.length > 1 &&
      volumenes[1] !== ":" &&
      !isNaN(parseFloat(volumenes[1]))
    ) {
      volumenHoy = parseFloat(volumenes[1]);
    }

    // ==============================
    // 3. EQUIVALENCIA + PRECIOS
    // ==============================
    const datosComerciales = lines[i + 1]
      ?.split(/\s+/)
      .filter(v => v !== "") || [];

    if (datosComerciales.length < 3) {
      continue;
    }

    // Primer número = equivalencia de la unidad en kg
    const equivalenciaKg = parseFloat(datosComerciales[0]);

    // MIDAGRI:
    // [0] equivalencia kg
    // [1] precio ayer
    // [2] precio hoy
    // [3] precio últimos 7 días
    const precioHoy = parseFloat(datosComerciales[2]);

    if (isNaN(precioHoy) || isNaN(equivalenciaKg)) {
      continue;
    }

    // ==============================
    // 4. RESULTADO
    // ==============================
    results.push({
      json: {
        fecha: fechaHistorica,
        producto: producto,
        mercado: "GMML",

        precio: precioHoy,

        // Masa de ingreso ya viene en toneladas desde MIDAGRI
        volumen_t: volumenHoy,

        // Equivalencia del volumen total en kg
        volumen_kg:
          volumenHoy !== null
            ? volumenHoy * 1000
            : null,

        // Unidad utilizada para comercializar / cotizar
        unidad: unidad,

        // Peso de UNA unidad comercial
        equivalencia_kg: equivalenciaKg
      }
    });
  }
}

return results;

